// HasWebform applies the HasEdge predicate on the "webform" edge.
func HasWebform() predicate.WebformElement {
	return predicate.WebformElement(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WebformTable, WebformColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWebformWith applies the HasEdge predicate on the "webform" edge with a given conditions (other predicates).
func HasWebformWith(preds ...predicate.Webform) predicate.WebformElement {
	return predicate.WebformElement(func(s *sql.Selector) {
		step := newWebformStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasValues applies the HasEdge predicate on the "values" edge.
